// Parse the dashboard's generate request (object-or-string body).
const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const job_id = (body.job_id || '').toString();
const field = (body.field || 'excerpt').toString();
const ALLOWED = ['excerpt', 'alt', 'meta_title', 'meta_description'];
return [{ json: { job_id, field: ALLOWED.indexOf(field) >= 0 ? field : 'excerpt' } }];

// Build the system + user prompt for the requested field.
const field = $('Parse Webhook Input').first().json.field;
const job = $('Get Job').first().json;

const SYSTEM = {
  excerpt: 'You write conversational blog excerpts. 150-160 characters. Hook the reader and summarize the angle in one tight sentence. Return ONLY JSON in this shape: {"excerpt":"..."} - no code fences, no commentary.',
  alt: 'You write concise descriptive alt text for blog cover images. Under 100 characters. Describe what is visually in the image. Return ONLY JSON in this shape: {"alt":"..."} - no code fences, no commentary.',
  meta_title: 'You write SEO meta titles. 50-60 characters. Include the main keyword naturally. Avoid clickbait. Return ONLY JSON in this shape: {"meta_title":"..."} - no code fences, no commentary.',
  meta_description: 'You write SEO meta descriptions. 150-160 characters. Include the main keyword and a soft CTA. Return ONLY JSON in this shape: {"meta_description":"..."} - no code fences, no commentary.'
};

function buildUser(field, job) {
  const topic = job.topic || '';
  const angle = job.chosen_angle || '';
  const draft = (job.draft_md || '').slice(0, 2000);
  const imgPrompt = job.image_prompt || '';
  if (field === 'alt') {
    return 'Topic: ' + topic + '\nImage prompt: ' + imgPrompt;
  }
  if (field === 'meta_description') {
    return 'Topic: ' + topic + '\nAngle: ' + angle + '\nDraft excerpt:\n' + draft.slice(0, 600);
  }
  return 'Topic: ' + topic + '\nAngle: ' + angle + '\nDraft (start):\n' + draft;
}

return [{ json: { field, system: SYSTEM[field] || SYSTEM.excerpt, user: buildUser(field, job) } }];

// Parse Claude's JSON, extract the requested field, return as { [field]: value }.
const res = $input.first().json;
const raw = (res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '';
let txt = raw.trim();
if (txt.startsWith('```')) {
  txt = txt.substring(txt.indexOf('\n') + 1);
  if (txt.endsWith('```')) txt = txt.slice(0, -3);
  txt = txt.trim();
}
let parsed = {};
try { parsed = JSON.parse(txt); } catch (e) { parsed = { error: e.message, raw }; }
const field = $('Parse Webhook Input').first().json.field;
const value = parsed[field] || '';
// With responseMode 'lastNode' the dashboard sees this object as the webhook response.
return [{ json: { [field]: value } }];
